update public.books set description_en = description, description = $mota$Bộ ba cuốn sách về những loài vật khác nhau.$mota$, description_auto_translated = true
where id = 272 and language = 'en' and description_en is null and md5(description) = '114e72badfa097c19a2ed4d8a070db98';

-- 273 the-art-of-eric-carle
update public.books set description_en = description, description = $mota$Carle là một trong những họa sĩ minh họa sách thiếu nhi được yêu mến nhất. Tuy vậy, cuốn sách hồi cố này không chỉ là sự tôn vinh nghệ thuật của ông. Sách còn có một tự truyện sâu sắc kèm ảnh riêng, một bài viết giàu giai thoại của biên tập viên lâu năm của ông, một bài viết bằng ảnh về cách Carle làm tranh cắt dán, cùng các bài viết của Carle và đồng nghiệp. Dù vậy, chính những bức tranh trong tập sách khổ lớn này mới là thứ cuốn hút trí tưởng tượng. Hơn 60 bức tranh cắt dán in màu toàn bộ của ông được tái hiện đẹp mắt, là minh chứng cho tài năng ấn tượng của Carle. (Booklist)$mota$, description_auto_translated = true
where id = 273 and language = 'en' and description_en is null and md5(description) = 'e779d3bb5aad8d3410fe180ca223de8b';

-- 274 the-eric-carle-library
update public.books set description_en = description, description = $mota$Những cuốn sách tranh tươi sáng, đầy sức sống của Eric Carle vẫn luôn khiến trẻ em tò mò với những câu đố vượt thời gian. Trong hộp quà này, ba cuốn sách bìa cứng kinh điển được bọc màng co riêng từng cuốn để trẻ đọc và tò mò không biết lời chúc sinh nhật sẽ dẫn đến đâu.$mota$, description_auto_translated = true
where id = 274 and language = 'en' and description_en is null and md5(description) = '7b9bcee59c10685e3a603edaf9d8ab94';

-- 275 a-book-of-things
update public.books set description_en = description, description = $mota$Học hơn 200 từ cùng The Very Hungry Caterpillar và những người bạn được yêu thích khác từ Thế giới của Eric Carle. Từ đồ ăn, quần áo đến con vật và cảm xúc, đây là cách hoàn hảo để các bé học những điều cần biết để khám phá thế giới bận rộn của mình. Tranh vẽ tươi sáng, nhiều màu sắc của Eric Carle cùng chữ in rõ ràng giúp việc học thật vui, và trang đôi ở cuối sách mời các bé nhớ lại mọi từ đã đọc.$mota$, description_auto_translated = true
where id = 275 and language = 'en' and description_en is null and md5(description) = 'b6525752eafda27f496f28859d248769';

-- 276 eric-carle-s-how-things-grow
update public.books set description_en = description, description = $mota$Cuốn mới nhất trong bộ sách bán chạy của Eric Carle! Nòng nọc thành ếch, hạt sồi thành cây sồi, và sâu bướm thành bướm. Khi lật những ô lật to và chắc chắn, các bạn đọc nhỏ sẽ khám phá thế giới xung quanh và cách mọi vật lớn lên qua những hình vẽ tươi sáng, đẹp mắt của Eric Carle. Người bạn đồng hành hoàn hảo của Eric Carle’s ABC, Opposites và All Around Us.$mota$, description_auto_translated = true
where id = 276 and language = 'en' and description_en is null and md5(description) = '19723bcd5688c7ec8a1f6b16986823f5';

-- 277 the-very-hungry-caterpillar-s-favorite-words
update public.books set description_en = description, description = $mota$Các bé sẽ thích lật giở cuốn sách bìa cứng dày dặn này, bước đầu tiên để tự đọc sách của Eric Carle! Sách có mười hình vẽ và mười từ dễ lấy từ những cuốn sách kinh điển của Eric Carle. Các bé mới tập đọc sẽ thích học những từ và hình này, rồi sau đó tìm lại chúng trong các cuốn sách tranh gốc!$mota$, description_auto_translated = true
where id = 277 and language = 'en' and description_en is null and md5(description) = 'e1928155412e9a42bc955653bab72a19';

-- 278 the-very-eric-carle-treasury
update public.books set description_en = description, description = $mota$Tuyển tập được làm riêng cho mùa lễ hội, hoàn hảo để cả gia đình cùng đọc! Bốn câu chuyện “Very” được yêu thích của tác giả Eric Carle, kèm công thức nấu ăn, hoạt động, dự án hoàn toàn mới và nhiều hơn nữa! Gồm The Very Busy Spider, The Very Quiet Cricket, The Very Lonely Firefly và The Very Clumsy Click Beetle, tuyển tập này mang đến cho người đọc trọn vẹn bốn cuốn sách “Very” trong một hộp sách tuyệt đẹp. Cùng với các câu chuyện, The Very Eric Carle Treasury có công thức nấu ăn, dự án gia đình và hoạt động cho từng cuốn, cùng một lá thư của chính Eric Carle! Dù bạn đã là người hâm mộ Carle hay lần đầu đọc truyện của ông, cuốn sách này là sự bổ sung hoàn hảo cho tủ sách của mọi gia đình. Lời khen dành cho bộ sách “Very” của Eric Carle: “Một tác phẩm được thực hiện tuyệt đẹp dành cho các bé.” (The Horn Book, bài điểm sách gắn sao). “Ngôn ngữ đơn giản, có nhịp điệu, lặp lại và điệp âm làm các bé thích thú khi nghe. Tranh cắt dán tô màu phong phú và giàu biểu cảm.” (School Library Journal). “Chắc chắn sẽ được yêu thích và được đòi đọc đi đọc lại, Click Beetle là câu chuyện được viết khéo léo, minh họa vui tươi, chạm đến trái tim trẻ nhỏ.” (Library Journal). “Tranh vẽ màu sắc đậm đà kiểu cắt dán và lời văn nhẹ nhàng của Carle sẽ quen thuộc và dễ chịu với đông đảo bạn đọc nhỏ hâm mộ ông.” (Publishers Weekly).$mota$, description_auto_translated = true
where id = 278 and language = 'en' and description_en is null and md5(description) = '23d7dedc2c921a99c7d841d6a2e08f5c';

-- 279 money
update public.books set description_en = description, description = $mota$Trích chọn từ hai cuốn Sapiens và Homo Deus của Yuval Noah Harari. Tiền được phát minh ra như thế nào? Vì sao ngày nay nó lại quan trọng đến vậy trong cuộc sống của chúng ta? Nó khiến ta hạnh phúc hơn hay bất hạnh hơn? Và tương lai nào đang chờ nó? Với sự sáng rõ và sâu sắc xuất sắc, Yuval Noah Harari đưa người đọc vào hành trình từ những đồng xu đầu tiên đến kinh tế học thế kỷ 21, và cho thấy tất cả chúng ta đang đứng trước một cuộc cách mạng, dù muốn hay không. Vintage Minis: trí tuệ lớn, ý tưởng lớn, sách nhỏ. Loạt sách ngắn của những nhà văn lớn nhất thế giới về những trải nghiệm làm nên con người. Cũng trong bộ Vintage Minis: Home của Salman Rushdie; Babies của Anne Enright; Eating của Nigella Lawson; Drinking của John Cheever.$mota$, description_auto_translated = true
where id = 279 and language = 'en' and description_en is null and md5(description) = '7b5928fb378c40e6af208ff0ac32e4c2';

-- 280 sapiens
update public.books set description_en = description, description = $mota$Sách bán chạy số 1 theo New York Times. Một trong 100 cuốn sách hay nhất thế kỷ 21 do độc giả New York Times bình chọn. Sách đọc mùa hè được Tổng thống Barack Obama và Bill Gates chọn. Ấn bản chính thức tại Mỹ, minh họa màu toàn bộ. Từ nhà sử học nổi tiếng Yuval Noah Harari, một câu chuyện đột phá về sự hình thành và tiến hóa của loài người, sách bán chạy số 1 thế giới, khám phá cách sinh học và lịch sử đã định nghĩa chúng ta và làm sâu sắc thêm hiểu biết về ý nghĩa của việc là “con người”. Một trăm nghìn năm trước, ít nhất sáu loài người khác nhau cùng sống trên Trái Đất. Thế nhưng ngày nay chỉ còn một: homo sapiens. Chuyện gì đã xảy ra với những loài kia? Và chuyện gì có thể xảy ra với chúng ta? Phần lớn sách về lịch sử loài người theo hướng tiếp cận lịch sử hoặc sinh học, nhưng Tiến sĩ Yuval Noah Harari phá vỡ khuôn mẫu với cuốn sách hết sức độc đáo này, bắt đầu từ khoảng 70.000 năm trước với sự xuất hiện của nhận thức hiện đại. Từ việc xem xét vai trò của loài người đang tiến hóa trong hệ sinh thái toàn cầu đến việc vẽ lại sự trỗi dậy của các đế chế, Sapiens kết hợp lịch sử và khoa học để nhìn lại những câu chuyện đã được chấp nhận, nối những diễn biến trong quá khứ với mối quan tâm thời nay, và xem xét các sự kiện cụ thể trong bối cảnh những ý tưởng lớn hơn. Tiến sĩ Harari còn buộc ta nhìn về phía trước, bởi trong vài thập kỷ qua, con người đã bắt đầu bẻ cong những quy luật chọn lọc tự nhiên vốn chi phối sự sống suốt bốn tỷ năm. Chúng ta đang có được khả năng thiết kế không chỉ thế giới xung quanh, mà cả chính bản thân mình. Điều này sẽ dẫn ta đến đâu, và ta muốn trở thành gì? Với 27 bức ảnh, 6 bản đồ và 25 hình minh họa, sơ đồ, tác phẩm gây suy ngẫm và sâu sắc này chắc chắn sẽ khơi dậy tranh luận và là sách không thể thiếu với những người yêu thích Jared Diamond, James Gleick, Matt Ridley, Robert Wright và Sharon Moalem.$mota$, description_auto_translated = true
where id = 280 and language = 'en' and description_en is null and md5(description) = 'a789b0f92d9f3fc37b19af87c335822c';

-- 282 21-lessons-for-the-21st-century
update public.books set description_en = description, description = $mota$Sách bán chạy số một. Qua hai mươi mốt bài học ngắn gọn, Yuval Noah Harari khám phá ý nghĩa của việc làm người trong một thời đại đầy hoang mang. Làm sao bảo vệ mình trước chiến tranh hạt nhân, thảm họa sinh thái và những đổ vỡ do công nghệ? Ta có thể làm gì trước nạn tin giả tràn lan hay mối đe dọa khủng bố? Ta nên dạy con cái điều gì? Nhà sử học và trí thức nổi tiếng thế giới Yuval Noah Harari đưa chúng ta vào một hành trình hấp dẫn qua những vấn đề cấp bách nhất hôm nay. Sợi chỉ vàng xuyên suốt cuốn sách mới đầy hứng khởi của ông là thách thức giữ được sự tập trung của cả tập thể lẫn mỗi cá nhân trước những thay đổi liên tục và gây chao đảo. Đối mặt với hàng loạt khủng hoảng hiện sinh và hiện thực, liệu chúng ta còn đủ sức hiểu thế giới mà chính mình đã tạo ra? “[Harari] đã mở ra một cuộc đối thoại toàn cầu quan trọng về cách đối mặt với các vấn đề của thế kỷ 21” (Bill Gates, New York Times). “Nói đơn giản, 21 Lessons là một cuốn sách quan trọng” (Adam Kay, tác giả Undoctored).$mota$, description_auto_translated = true
where id = 282 and language = 'en' and description_en is null and md5(description) = 'bef1fcde1446dcb5ee156df8ae310fbf';

-- 283 unstoppable-us-the-two-book-boxed-set
update public.books set description_en = description, description = $mota$Tìm hiểu loài người thời sơ khai đã chiếm lĩnh Trái Đất NHƯ THẾ NÀO và VÌ SAO thế giới họ xây dựng lại không công bằng, với hộp sách hai tập của bộ Unstoppable Us bán chạy theo New York Times. Tác giả của Sapiens đưa độc giả tuổi trung học cơ sở vào một chuyến du hành hoành tráng, hấp dẫn qua lịch sử loài người thuở ban đầu trong những cuốn sách minh họa đẹp mắt này. “Lôi cuốn và gợi nhiều suy ngẫm.” (The New York Times). Unstoppable Us, Tập 1: How Humans Took Over the World. Loài người là giống loài thống trị nhất từng tồn tại. Nhưng làm sao ta đến được vị trí đó? Câu trả lời là một trong những câu chuyện kỳ lạ nhất bạn từng nghe… Unstoppable Us, Tập 2: Why the World Isn't Fair. Chuyện gì xảy ra tiếp theo? Tổ tiên săn bắt hái lượm của chúng ta đã trở thành nông dân ra sao? Vì sao các vương quốc và luật lệ ra đời? Làm sao ta đi từ chỗ làm chủ Trái Đất đến chỗ làm chủ lẫn nhau? Tác giả nổi tiếng Yuval Noah Harari đã khéo léo dựng nên hai câu chuyện phi thường về cách loài người học để không chỉ sống sót mà còn phát triển mạnh mẽ trên Trái Đất, kèm bản đồ, dòng thời gian và tranh minh họa màu toàn bộ làm sống động lối viết sinh động, khó rời mắt của ông.$mota$, description_auto_translated = true
where id = 283 and language = 'en' and description_en is null and md5(description) = '98605f5da59273ec1e24e183e4fcf58d';

-- 284 nexus
update public.books set description_en = description, description = $mota$Sách bán chạy số 1 theo New York Times. Từ tác giả của Sapiens, câu chuyện đột phá về cách các mạng lưới thông tin đã tạo dựng, và phá hủy, thế giới của chúng ta. “Độc đáo đến kinh ngạc… Một sử gia có lập luận vận hành ở quy mô hàng thiên niên kỷ đã nắm bắt hoàn hảo tinh thần thời đại.” (The Economist). “Cuốn sách hết sức quan trọng này ra đời vào thời điểm then chốt, khi tất cả chúng ta đang suy nghĩ thấu đáo về hệ quả của AI và việc sản xuất nội dung tự động… Bậc thầy và đầy khiêu khích.” (Mustafa Suleyman, tác giả The Coming Wave). Trong 100.000 năm qua, loài Sapiens chúng ta đã tích lũy quyền lực khổng lồ. Nhưng bất chấp mọi khám phá, phát minh và chinh phục, giờ đây ta lại rơi vào một cuộc khủng hoảng hiện sinh. Thế giới đang bên bờ sụp đổ sinh thái. Thông tin sai lệch tràn lan. Và ta đang lao đầu vào thời đại AI, một mạng lưới thông tin mới đe dọa hủy diệt chính chúng ta. Với tất cả những gì đã đạt được, vì sao ta lại tự hủy hoại đến thế? Nexus nhìn qua lăng kính dài của lịch sử loài người để xem dòng chảy thông tin đã định hình chúng ta và thế giới ra sao. Đưa ta đi từ Thời kỳ Đồ đá, qua việc định điển Kinh Thánh, những cuộc săn phù thủy đầu thời cận đại, chủ nghĩa Stalin, chủ nghĩa Quốc xã, đến sự trỗi dậy của chủ nghĩa dân túy ngày nay, Yuval Noah Harari mời ta suy ngẫm về mối quan hệ phức tạp giữa thông tin và sự thật, bộ máy quan liêu và thần thoại, trí tuệ và quyền lực. Ông khám phá cách các xã hội và hệ thống chính trị khác nhau trong lịch sử đã dùng thông tin để đạt mục đích, cả tốt lẫn xấu. Và ông bàn đến những lựa chọn cấp bách ta phải đối mặt khi trí tuệ phi nhân loại đe dọa chính sự tồn tại của ta. Thông tin không phải nguyên liệu thô của sự thật; nó cũng không chỉ là vũ khí. Nexus khám phá vùng trung gian đầy hy vọng giữa hai thái cực ấy, và qua đó tìm lại nhân tính chung của chúng ta.$mota$, description_auto_translated = true
where id = 284 and language = 'en' and description_en is null and md5(description) = '73f70971629ab59a19b49ccefb52109a';

-- 285 the-grand-design
update public.books set description_en = description, description = $mota$Vũ trụ bắt đầu khi nào và như thế nào? Vì sao chúng ta ở đây? Phải chăng “thiết kế vĩ đại” mà ta thấy ở vũ trụ là bằng chứng cho một đấng sáng tạo nhân từ đã khởi động mọi thứ? Hay khoa học đưa ra một lời giải thích khác? Trong The Grand Design, những tư tưởng khoa học mới nhất về các bí ẩn của vũ trụ được trình bày bằng ngôn ngữ vừa xuất sắc vừa giản dị. Thuyết hiện thực phụ thuộc mô hình, đa vũ trụ, thuyết vũ trụ học từ trên xuống và thuyết M thống nhất: tất cả đều được hé lộ ở đây. Đây là tác phẩm lớn đầu tiên sau gần một thập kỷ của một trong những nhà tư tưởng vĩ đại nhất thế giới. Là cẩm nang súc tích, gây sửng sốt và minh họa phong phú về những khám phá đang thay đổi hiểu biết của ta và lung lay một số hệ niềm tin được trân quý nhất, The Grand Design là cuốn sách mang lại hiểu biết, và gây tranh luận, như không cuốn nào khác.$mota$, description_auto_translated = true
where id = 285 and language = 'en' and description_en is null and md5(description) = '5ae590d852d205daec3f03421e80a959';

-- 286 a-briefer-history-of-time
update public.books set description_en = description, description = $mota$Các tác giả có sách bán chạy số 1 theo New York Times. Tác phẩm khoa học kinh điển nay dễ tiếp cận hơn, súc tích hơn, có minh họa. Từ một trong những bộ óc lỗi lạc nhất thời đại, cuốn sách làm sáng rõ những ý tưởng quan trọng nhất của ông. A Brief History of Time, cuốn sách bán chạy toàn cầu của Stephen Hawking, vẫn là một cột mốc của sách khoa học. Nhưng nhiều năm nay độc giả mong có một cách trình bày dễ hiểu hơn cho các khái niệm then chốt của nó: bản chất của không gian và thời gian, vai trò của Chúa trong sự sáng tạo, lịch sử và tương lai của vũ trụ. A Briefer History of Time là câu trả lời của Giáo sư Hawking. Dù “ngắn gọn hơn”, cuốn sách không chỉ đơn thuần giải thích tác phẩm trước đó của Hawking. A Briefer History of Time vừa làm rõ vừa mở rộng những chủ đề lớn của bản gốc, đồng thời ghi lại những bước tiến mới nhất trong lĩnh vực, từ lý thuyết dây đến cuộc tìm kiếm một lý thuyết thống nhất mọi lực của vật lý. Ba mươi bảy hình minh họa màu làm phong phú thêm nội dung và khiến A Briefer History of Time tự thân trở thành một bổ sung hào hứng, không thể thiếu cho kho tàng sách khoa học và tư tưởng.$mota$, description_auto_translated = true
where id = 286 and language = 'en' and description_en is null and md5(description) = 'bd763f034a9f6949e9fa99b632e8b044';

-- 287 black-holes-the-reith-lectures
update public.books set description_en = description, description = $mota$“Người ta nói đôi khi sự thật còn lạ hơn hư cấu, và điều đó đúng hơn ở đâu hết với hố đen. Hố đen kỳ lạ hơn bất cứ thứ gì các nhà văn khoa học viễn tưởng từng mơ tới.” Năm 2016, Giáo sư Stephen Hawking trình bày loạt bài giảng Reith Lectures của BBC về một chủ đề đã cuốn hút ông suốt nhiều thập kỷ: hố đen. Trong loạt bài giảng tiêu biểu này, nhà vật lý huyền thoại lập luận rằng chỉ cần hiểu được hố đen và cách chúng thách thức chính bản chất của không gian và thời gian, chúng ta có thể mở khóa những bí mật của vũ trụ.$mota$, description_auto_translated = true
where id = 287 and language = 'en' and description_en is null and md5(description) = '852456f79a9a3655b350999cbdc0a7e4';

-- 288 the-illustrated-brief-history-of-time
update public.books set description_en = description, description = $mota$Ấn bản cập nhật, mở rộng và có minh họa của tác phẩm kinh điển của Stephen Hawking, gồm những bước tiến mới nhất trong lĩnh vực, nhiều điều trong số đó đã được ông dự báo. Trong ấn bản này, Giáo sư Hawking giải thích các lý thuyết phức tạp của mình qua một chiều kích thị giác mới mẻ. Hơn một trăm năm mươi hình minh họa màu tuyệt đẹp được đặt vẽ riêng cho mục đích này, giúp người đọc hiểu những điều đã trở thành hình ảnh huyền thoại phổ biến của thế kỷ chúng ta, nhưng vẫn là những ý tưởng trừu tượng, khó nắm bắt.$mota$, description_auto_translated = true
where id = 288 and language = 'en' and description_en is null and md5(description) = '2e3b6173b4b36ff4d9583dd9d4c3f08a';

-- 289 the-universe-in-a-nutshell
update public.books set description_en = description, description = $mota$Trong phần tiếp nối xuất sắc của A Brief History of Time, cuốn sách thành công phi thường, Stephen Hawking giải mã những đột phá lý thuyết đáng kinh ngạc diễn ra trong thập kỷ sau khi cuốn sách bán chạy ấy ra đời. Với lối viết uyên bác mà dễ hiểu, Hawking dẫn ta qua sự phát triển của thuyết tương đối của Einstein, nguyên lý bất định, cơ học lượng tử, năm lý thuyết dây, thuyết M và những p-brane bí ẩn dường như mở đường đến chén thánh của vật lý lý thuyết: TOE, Thuyết vạn vật (Theory of Everything). Ông truyền đạt niềm phấn khích hiện có trong giới khoa học khi cùng ta du hành qua một vũ trụ mười chiều như xứ sở của Alice, có lẽ chỉ là một trong nhiều lịch sử khả dĩ, nơi hố đen bốc hơi, siêu dây cuộn lại và các vũ trụ song song co lại thành hư vô. Được minh họa đẹp mắt từ đầu đến cuối bằng tranh vẽ đặt riêng cho dự án này, The Universe in a Nutshell chắc chắn sẽ là cuốn sách khoa học lớn nhất năm 2001.$mota$, description_auto_translated = true
where id = 289 and language = 'en' and description_en is null and md5(description) = '53fb6d7ef7abb2ac7857111ab61835f1';

-- 290 black-holes-and-baby-universes
update public.books set description_en = description, description = $mota$Sách bán chạy theo New York Times. Mười ba tiểu luận phi thường soi rọi bí ẩn của vũ trụ, và một trong những nhà tư tưởng lỗi lạc nhất thời đại, dưới ánh sáng mới. Với cuốn sách bán chạy phi thường A Brief History of Time, Stephen Hawking đã thực sự thay đổi cách ta nghĩ về vật lý, vũ trụ và chính thực tại. Trong mười ba tiểu luận và một cuộc phỏng vấn dài đặc sắc này, người được nhiều người xem là nhà vật lý lý thuyết lỗi lạc nhất kể từ Einstein trở lại để hé lộ hàng loạt khả năng đáng kinh ngạc giúp ta hiểu vũ trụ. Dựa trên những công trình trước đó, Hawking bàn về thời gian ảo, cách hố đen có thể sinh ra những vũ trụ con, và nỗ lực của các nhà khoa học nhằm tìm một lý thuyết thống nhất hoàn chỉnh có thể dự đoán mọi thứ trong vũ trụ. Với tài sử dụng ngôn ngữ đặc trưng, óc hài hước và cách nói giản dị, Stephen Hawking mời ta hiểu ông hơn, và cùng chia sẻ niềm đam mê với cuộc du hành của trí tuệ và trí tưởng tượng đã mở ra những con đường mới để hiểu chính bản chất của vũ trụ.$mota$, description_auto_translated = true
where id = 290 and language = 'en' and description_en is null and md5(description) = '229b77b557f40115d344fb8ec9335814';

-- 291 brief-answers-to-the-big-questions
update public.books set description_en = description, description = $mota$Sách bán chạy số 1 theo Sunday Times. “Một cuốn sách nhỏ tuyệt đẹp của một bộ óc lỗi lạc” (Daily Telegraph). “Dạy ta nhiều điều một cách nhẹ nhàng, cuốn hút, cập nhật và, ở những chỗ cần thiết, dí dỏm” (Guardian). Nhà vũ trụ học nổi tiếng thế giới, tác giả của cuốn sách bán chạy số 1 A Brief History of Time, để lại cho chúng ta những suy nghĩ cuối cùng về các câu hỏi lớn nhất của vũ trụ trong tác phẩm xuất sắc xuất bản sau khi ông qua đời này. Có Chúa không? Mọi thứ đã bắt đầu thế nào? Ta có thể dự đoán tương lai không? Bên trong hố đen có gì? Có sự sống thông minh nào khác trong vũ trụ không? Trí tuệ nhân tạo có vượt mặt chúng ta không? Ta định hình tương lai ra sao? Ta có sống sót trên Trái Đất không? Có nên định cư ngoài không gian? Du hành thời gian có khả thi không? Trong suốt sự nghiệp phi thường của mình, Stephen Hawking đã mở rộng hiểu biết của ta về vũ trụ và giải mã một số bí ẩn lớn nhất của nó. Nhưng ngay cả khi các công trình lý thuyết về hố đen, thời gian ảo và đa lịch sử đưa tâm trí ông tới những miền xa nhất của không gian, Hawking vẫn luôn tin rằng khoa học cũng có thể dùng để giải quyết các vấn đề trên hành tinh này. Và giờ đây, khi ta đối mặt với những thay đổi có thể mang tính thảm họa ngay trên Trái Đất, từ biến đổi khí hậu, tài nguyên thiên nhiên cạn dần đến mối đe dọa của siêu trí tuệ nhân tạo, Stephen Hawking hướng sự chú ý tới những vấn đề cấp bách nhất của loài người. Bao quát, kích thích trí tuệ, lập luận đầy nhiệt huyết và thấm đẫm óc hài hước đặc trưng của ông, Brief Answers to the Big Questions, cuốn sách cuối cùng của một trong những bộ óc vĩ đại nhất lịch sử, là góc nhìn riêng của ông về những thách thức loài người đang đối mặt, và về nơi hành tinh chúng ta sẽ hướng tới. Một phần tiền bản quyền sẽ được dành cho từ thiện.$mota$, description_auto_translated = true
where id = 291 and language = 'en' and description_en is null and md5(description) = 'da10f9736f47f6037ed03aa60ac4177c';

-- 293 you-and-the-universe
update public.books set description_en = description, description = $mota$Khơi gợi để trẻ đặt những câu hỏi lớn về Trái Đất và vũ trụ với phiên bản minh họa tuyệt đẹp này của thông điệp cuối cùng Giáo sư Stephen Hawking gửi tới nhân loại. Tất cả chúng ta đều là những người du hành thời gian, cùng nhau đi vào tương lai. Nhưng hãy cùng nhau làm cho tương lai ấy thành nơi ta muốn đến. Nhà khoa học và nhà giáo dục Stephen Hawking đã dành cả đời để giải mã những bí ẩn của vũ trụ. Nhưng ông vẫn còn nhiều câu hỏi, và ông muốn mọi độc giả, mọi đứa trẻ, cùng chung tay giúp trả lời: làm sao để cứu hành tinh? Làm sao để học cách luôn ở bên nhau? Chuyển thể từ thông điệp Ngày Trái Đất năm 2020 được công bố sau khi Giáo sư Hawking qua đời, You and the Universe là cuốn sách tranh đầu tiên của ông và là lời tri ân dành cho những công dân nhỏ tuổi nhất của Trái Đất, đề cao sức mạnh của sự đoàn kết và cùng tạo dựng một ngày mai tốt đẹp hơn.$mota$, description_auto_translated = true
where id = 293 and language = 'en' and description_en is null and md5(description) = '71a984dc89c648983bba9064da3aabed';

-- 294 a-brief-history-of-time-6923
update public.books set description_en = description, description = $mota$Sách bán chạy số 1 theo New York Times. Là một cột mốc của sách khoa học do một trong những bộ óc vĩ đại của thời đại viết, cuốn sách của Stephen Hawking khám phá những câu hỏi sâu xa như: vũ trụ bắt đầu thế nào, và điều gì khiến khởi đầu ấy khả thi? Thời gian có luôn trôi về phía trước? Vũ trụ là vô tận, hay có biên giới? Không gian có những chiều khác không? Điều gì sẽ xảy ra khi mọi thứ kết thúc? Được kể bằng ngôn ngữ ai cũng hiểu, A Brief History of Time đưa ta vào những miền kỳ lạ của hố đen và hạt quark, của phản vật chất và “mũi tên thời gian”, của vụ nổ lớn và một Thượng đế còn lớn hơn, nơi những khả năng thật kỳ diệu và bất ngờ. Với những hình ảnh hấp dẫn và trí tưởng tượng sâu sắc, Stephen Hawking đưa ta đến gần hơn những bí mật tối hậu nằm ở chính trái tim của tạo hóa.$mota$, description_auto_translated = true
where id = 294 and language = 'en' and description_en is null and md5(description) = 'b41891e076cef7da41a103a562c07734';

-- 295 the-large-the-small-and-the-human-mind
update public.books set description_en = description, description = $mota$Những ý tưởng độc đáo và gây tranh cãi của Roger Penrose về vật lý của Vũ trụ ở quy mô lớn, thế giới vi mô của vật lý lượng tử và vật lý của tâm trí đã là đề tài của nhiều tranh luận. Các ý tưởng này được nêu trong những cuốn sách bán chạy của ông, The Emperor's New Mind và Shadows of the Mind. Trong cuốn sách này, ông tóm lược và cập nhật suy nghĩ hiện tại của mình về các lĩnh vực phức tạp ấy, đưa ra một bản tổng kết bậc thầy về những lĩnh vực vật lý mà ông cho là còn những vấn đề lớn chưa có lời giải. Qua đó, ông giới thiệu những khái niệm hoàn toàn mới mà ông tin sẽ hữu ích để hiểu cách bộ não vận hành và bản chất của tâm trí con người. Những ý tưởng này được ba chuyên gia xuất sắc thuộc các lĩnh vực khác nhau phản biện: Abner Shimony và Nancy Cartwright với tư cách nhà triết học khoa học, và Stephen Hawking với tư cách nhà vật lý lý thuyết và vũ trụ học. Roger Penrose kết thúc bằng phần đáp lại những phê bình gợi suy ngẫm của họ.$mota$, description_auto_translated = true
where id = 295 and language = 'en' and description_en is null and md5(description) = '57f8df28fc501b1d41856be6578a2cbc';

-- 296 carl-sagan-s-cosmic-connection
update public.books set description_en = description, description = $mota$Cuốn sách kinh điển của nhà khoa học và nhà tiên phong khoa học nổi tiếng nhất thế giới, nay được tái bản với một góc nhìn mới.$mota$, description_auto_translated = true
where id = 296 and language = 'en' and description_en is null and md5(description) = 'b1eaf15d918e3f7f2dac440b9d9da4fe';

-- 297 billions-billions
update public.books set description_en = description, description = $mota$Sách bán chạy theo New York Times. Trong cuốn sách cuối cùng của sự nghiệp phi thường, Carl Sagan xem xét tài tình những câu hỏi nóng bỏng về cuộc sống, thế giới và vũ trụ quanh ta. Những tiểu luận sáng rõ, thú vị này đi qua cả sự bao la của vũ trụ lẫn những góc sâu kín của tâm trí con người, đặt ra những câu hỏi hấp dẫn như vũ trụ bắt nguồn từ đâu và sẽ kết thúc ra sao, làm sao kết hợp khoa học với lòng trắc ẩn để đối mặt với thách thức của thế kỷ tới. Sách cũng hé lộ hiếm hoi những suy nghĩ riêng tư của Sagan về tình yêu, cái chết và Thượng đế khi ông chống chọi với căn bệnh hiểm nghèo. Luôn hướng về phía trước và rạng rỡ ánh lấp lánh của sự tò mò không bao giờ tắt, Billions & Billions là minh chứng cho một trong những bộ óc khoa học vĩ đại của thời đại. Lời khen dành cho Billions & Billions: “Văn của [Sagan] tràn đầy lạc quan, sáng rõ và nhân ái.” (Ft. Lauderdale Sun-Sentinel). “Sagan đã dùng ánh đèn danh tiếng của mình để soi sáng vực thẳm mà sự ngu dốt, lòng tham và khát vọng quyền lực có thể đẩy ta xuống. Mọi mối quan tâm và lý tưởng ấy đều được thể hiện trọn vẹn trong Billions & Billions.” (The Washington Post Book World). “Nhà thiên văn Carl Sagan không sống đến thiên niên kỷ mới, nhưng có lẽ ông đã làm nhiều hơn bất kỳ nhà khoa học đại chúng nào khác để chuẩn bị cho chúng ta đón nó.” (Atlanta Journal & Constitution). “Billions & Billions có thể được xem là Silent Spring của thế hệ hôm nay… Lịch sử loài người có không ít bộ óc lớn đã đưa ra những lý thuyết về vũ trụ và nguồn gốc của chúng ta đi ngược giáo điều tôn giáo. Galileo xác định Trái Đất quay quanh Mặt Trời chứ không phải ngược lại. Darwin thách thức thuyết Sáng tạo bằng thuyết tiến hóa của các loài. Và giờ đây, Sagan đã trao cho thế giới thách thức mới nhất: Billions & Billions.” (San Antonio Express-News). “Cảm hứng và sự tò mò vô bờ của [Sagan] vẫn sống mãi trong món quà là các tác phẩm của ông.” (Seattle Times & Post-Intelligencer). “Không thể tỉnh táo trong giờ khoa học ở trường trung học? Cuốn sách này có thể giúp bạn lấp những lỗ hổng. Nhà khoa học nổi tiếng Carl Sagan kết hợp logic và kiến thức với sự dí dỏm, hài hước để biến một chủ đề có thể khô khan thành thú vị.” (The Dallas Morning News).$mota$, description_auto_translated = true
where id = 297 and language = 'en' and description_en is null and md5(description) = '524db6a5f51697555faecc979866d835';

-- 298 contact
update public.books set description_en = description, description = $mota$Nhà văn, nhà thiên văn từng đoạt giải Pulitzer Carl Sagan tưởng tượng ra cuộc phiêu lưu vĩ đại nhất: khám phá một nền văn minh tiên tiến trong lòng không gian sâu thẳm. Tháng 12 năm 1999, một nhóm đa quốc gia du hành tới các vì sao, đến với cuộc gặp gỡ choáng ngợp nhất trong lịch sử loài người. Ai, hay điều gì, đang ở ngoài kia? Trong Cosmos, Carl Sagan giải thích vũ trụ. Trong Contact, ông dự đoán tương lai của vũ trụ, và của chính chúng ta.$mota$, description_auto_translated = true
where id = 298 and language = 'en' and description_en is null and md5(description) = 'a256217e49a4b2fda3557784ba142d52';

-- 299 broca-s-brain
update public.books set description_en = description, description = $mota$Cuốn sách hấp dẫn về niềm vui khám phá cách thế giới vận hành, của tác giả từng đoạt giải Pulitzer với Cosmos và Shadows of Forgotten Ancestors. “Tuyệt vời… Thú vị… Một kiệt tác. Một thông điệp đầy hy vọng cho nhân loại… Dù luôn ý thức rằng sự điên rồ của con người có thể chấm dứt bước tiến của nhân loại vào tương lai, Sagan vẫn vẽ cho ta một tương lai choáng ngợp: robot thông minh, việc phát hiện sự sống ngoài Trái Đất cùng những hệ quả của nó, và trên hết là thách thức, hành trình theo đuổi bí ẩn của vũ trụ.” (Chicago Tribune). “Hãy ra ngoài mua cuốn sách này, vì Carl Sagan không chỉ là một trong những nhà khoa học được kính trọng nhất thế giới, ông còn là một cây bút tuyệt vời… Lời khen lớn nhất tôi có thể dành cho một cuốn sách là nói rằng tôi định đọc lại nó. Lần nữa. Và lần nữa.” (The Miami Herald). “Nhà thiên văn lỗi lạc… viết thuyết phục, khơi gợi suy nghĩ và dễ đọc.” (United Press International). “Lập luận chặt chẽ, nghiên cứu hoàn hảo, hài hước nhẹ nhàng, sắc bén, không khoan nhượng.” (The Washington Post).$mota$, description_auto_translated = true
where id = 299 and language = 'en' and description_en is null and md5(description) = 'a3f23561000f41b0cbb2fafb88e44302';

-- 300 dragons-of-eden
update public.books set description_en = description, description = $mota$“Lịch sử bộ não con người từ vụ nổ lớn mười lăm tỷ năm trước đến hôm kia… Thật thú vị.” (The New York Times). Tiến sĩ Carl Sagan đưa ta vào một cuộc phiêu lưu đọc tuyệt vời, với những nhận định sinh động và bất ngờ về bộ não của người và thú, nguồn gốc trí thông minh của con người, vai trò của những truyền thuyết ám ảnh nhất, và mối liên hệ đáng kinh ngạc của chúng với những khám phá gần đây. “Làm sao để thuyết phục mọi người thông minh đọc cuốn sách quan trọng và thanh nhã này? … Ông nói về đủ mọi chuyện: vì sao người mẹ đau khi sinh nở… lý do của giấc ngủ và giấc mơ… những con tinh tinh được dạy giao tiếp bằng ngôn ngữ ký hiệu… định nghĩa về cái chết… nhân bản vô tính… máy tính… sự sống thông minh trên các hành tinh khác… Hấp dẫn… thú vị.” (The Boston Globe). “Ở một vườn Địa đàng đã mất, nơi rồng thống trị, nền móng trí thông minh của chúng ta đã được đặt xuống… Carl Sagan dẫn ta đi tham quan miền đất đã mất ấy… Hấp dẫn… thú vị… bậc thầy.” (St. Louis Post-Dispatch).$mota$, description_auto_translated = true
where id = 300 and language = 'en' and description_en is null and md5(description) = '793bb6d102b81337f4cc21b55a23eb2b';

-- 301 cosmos
update public.books set description_en = description, description = $mota$Cuốn sách kinh điển bán chạy của nhà thiên văn nổi tiếng Carl Sagan, “lặn sâu vào quá khứ, hiện tại và tương lai của khoa học, đối diện với sự bao la choáng ngợp của vũ trụ nơi chúng ta tồn tại” (Associated Press), kèm lời giới thiệu của Ann Druyan và lời tựa của Neil deGrasse Tyson. “Sagan làm trí óc choáng ngợp với phép màu về sự tồn tại của chúng ta, trong khung cảnh những thiên hà uy nghi của không gian.” (Cosmopolitan). Nguồn cảm hứng cho loạt phim ngắn Cosmos: Possible Worlds của kênh FOX, do Neil deGrasse Tyson dẫn chương trình, với sự tham gia của Seth MacFarlane và Sir Patrick Stewart. Bằng văn xuôi sáng rõ, Carl Sagan hé lộ một thế giới xanh như viên ngọc, nơi sinh sống của một dạng sống vừa bắt đầu khám phá bản sắc của chính mình và mạo hiểm bước ra đại dương bao la của không gian. Với hình minh họa màu, Cosmos lần lại mười bốn tỷ năm tiến hóa vũ trụ đã biến vật chất thành ý thức, khám phá những chủ đề như nguồn gốc sự sống, bộ não con người, chữ tượng hình Ai Cập, các sứ mệnh tàu vũ trụ, cái chết của Mặt Trời, sự tiến hóa của các thiên hà, cùng những động lực và con người đã góp phần định hình khoa học hiện đại.$mota$, description_auto_translated = true
where id = 301 and language = 'en' and description_en is null and md5(description) = 'a934e16d2d3f99516d7726d5bdc8475d';

-- 302 murmurs-of-earth
update public.books set description_en = description, description = $mota$Đĩa ghi âm liên sao của tàu Voyager.$mota$, description_auto_translated = true
where id = 302 and language = 'en' and description_en is null and md5(description) = 'bafd44dcdaa82cc828a0688407a8415e';

-- 303 pale-blue-dot
update public.books set description_en = description, description = $mota$“Hấp dẫn… đáng nhớ… giàu khám phá… có lẽ là cuốn hay nhất của Carl Sagan.” (The Washington Post Book World, bài điểm sách trang nhất). Trong Cosmos, cố nhà thiên văn Carl Sagan đã hướng ánh nhìn về bí ẩn kỳ vĩ của Vũ trụ và đưa nó đến với hàng triệu người khắp thế giới. Giờ đây, trong phần tiếp nối tuyệt vời này, Carl Sagan hoàn tất hành trình mang tính cách mạng xuyên không gian và thời gian. Các thế hệ sau sẽ nhìn lại thời đại chúng ta như lúc loài người cuối cùng cũng bước vào một biên cương hoàn toàn mới: không gian. Trong Pale Blue Dot, Sagan lần lại lịch sử đầy mê hoặc của hành trình con người vươn ra vũ trụ và đánh giá tương lai đang chờ phía trước khi ta tiến ra hệ Mặt Trời của mình rồi tới những thiên hà xa xôi. Sagan khẳng định việc khám phá và cuối cùng định cư ở những thế giới khác không phải chuyện viển vông hay xa xỉ, mà là điều kiện cần cho sự tồn vong của loài người. “Đưa người đọc đi xa hơn Cosmos rất nhiều… Sagan nhìn thấy tương lai nhân loại giữa các vì sao.” (Chicago Tribune).$mota$, description_auto_translated = true
where id = 303 and language = 'en' and description_en is null and md5(description) = 'aa30ec11d1c571a1b2bd120cd301d3e7';

-- 304 the-varieties-of-scientific-experience
update public.books set description_en = description, description = $mota$“Ann Druyan đã khai quật được một kho báu. Đó là kho báu của lý trí, lòng trắc ẩn và niềm kính sợ khoa học. Đó nên là cuốn sách tiếp theo bạn đọc.” (Sam Harris, tác giả The End of Faith). “Một di sản giá trị đến sửng sốt mà một con người vĩ đại để lại cho tất cả chúng ta. Tôi nhớ ông ấy biết bao.” (Kurt Vonnegut). Tầm nhìn tiên tri của Carl Sagan về sự trỗi dậy bi thảm của chủ nghĩa chính thống và tiềm năng đầy hy vọng của bước phát triển lớn tiếp theo trong đời sống tâm linh của con người. Cố nhà thiên văn và vật lý thiên văn vĩ đại kể về hành trình riêng tìm hiểu bản chất của điều thiêng liêng giữa sự bao la của vũ trụ. Với tầm hiểu biết rộng đến kinh ngạc, Sagan trình bày quan điểm về nhiều chủ đề, như khả năng tồn tại sự sống thông minh trên các hành tinh khác, thuyết sáng tạo và cái gọi là thiết kế thông minh, và một quan niệm mới về khoa học như một sự “tôn thờ có hiểu biết”. Vốn được trình bày tại lễ kỷ niệm một trăm năm loạt bài giảng Gifford nổi tiếng ở Scotland năm 1985 nhưng chưa từng được xuất bản, cuốn sách mang đến cuộc gặp gỡ độc nhất với một trong những bộ óc đáng chú ý nhất thế kỷ 20.$mota$, description_auto_translated = true
where id = 304 and language = 'en' and description_en is null and md5(description) = 'ea6acd58b7d785cf27522e7ee46d0636';

-- 305 at-home
update public.books set description_en = description, description = $mota$Bill Bryson sở hữu một trong những bộ óc sinh động và ham tìm hiểu nhất hành tinh, và At Home nhiều khả năng sẽ trở thành cuốn sách soi sáng nhất từng được viết về cách chúng ta đã sống ngày trước và đang sống hôm nay: vì sao, ở đâu và như thế nào. Giờ đây, trong ấn bản mới đẹp mắt này, lối văn lấp lánh của ông được tôn thêm bởi khoảng 200 hình ảnh màu được chọn lọc kỹ, từ quá khứ đến hiện tại. Được chọn từ vô số nguồn để làm sống động hành trình của Bill, những hình ảnh này sẽ khiến việc đọc At Home thành một trải nghiệm đắm chìm. Đọc xong cuốn sách, bạn sẽ nhìn ngôi nhà của mình, và cuộc sống hằng ngày của mình, dưới một ánh sáng mới đầy khám phá.$mota$, description_auto_translated = true
where id = 305 and language = 'en' and description_en is null and md5(description) = 'dfb1d84aa33271ce916d6868084c8d53';

-- 306 the-body
update public.books set description_en = description, description = $mota$Sách bán chạy số 1 cả bản bìa cứng lẫn bìa mềm, lọt vào danh sách rút gọn Giải sách khoa học Royal Society Insight Investment 2020. “Một danh mục những điều kỳ diệu.” (The Guardian). “Kinh ngạc đến há hốc miệng.” (The Times). “Đúng chất Bryson kinh điển, hóm hỉnh, hân hoan… một cuốn sách thú vị và đầy ắp sự thật.” (The Sunday Times). “Thật là tài kể chuyện khi nhồi được ngần ấy sự thật vào một cuốn sách vừa thú vị vừa bổ ích.” (The Daily Telegraph). “Chúng ta sống cả đời trong một cơ thể, vậy mà phần lớn gần như không biết nó hoạt động ra sao và bên trong diễn ra những gì. Ý tưởng của cuốn sách chỉ đơn giản là cố hiểu cỗ máy phi thường chính là chúng ta.” Bill Bryson lên đường khám phá cơ thể con người, cách nó vận hành và khả năng tự chữa lành đáng kinh ngạc của nó. Đầy những sự thật phi thường và câu chuyện đáng kinh ngạc, The Body: A Guide for Occupants là một nỗ lực xuất sắc, thường rất hài hước, nhằm hiểu phép màu của cấu tạo thể chất và thần kinh của chúng ta. Là phần kế tục tuyệt vời của A Short History of Nearly Everything, cuốn sách mới này lập tức trở thành kinh điển. Nó sẽ khiến bạn hết lần này đến lần khác kinh ngạc trước hình hài mình đang trú ngụ và tôn vinh sự kỳ diệu của chính sự tồn tại của bạn. “Điều tôi học được là chúng ta phức tạp và kỳ diệu hơn vô cùng, và thường bí ẩn hơn, so với những gì tôi từng nghĩ. Thật sự không có câu chuyện nào đáng kinh ngạc hơn câu chuyện về chính chúng ta.” (Bill Bryson).$mota$, description_auto_translated = true
where id = 306 and language = 'en' and description_en is null and md5(description) = '59d1f1a91f4f161bdff490c2fc0b3706';

-- 307 the-mother-tongue
update public.books set description_en = description, description = $mota$“Vô cùng bổ ích và vô cùng thú vị… Một cuốn sách uyên bác và hấp dẫn.” (Los Angeles Times). Với sự dí dỏm rực rỡ và óc quan sát đáng kinh ngạc, Bill Bryson khám phá lịch sử phi thường, những điều kỳ quặc, sức sống bền bỉ và niềm vui thuần túy của tiếng Anh. Từ lần đầu thanh quản tụt xuống cổ họng (vì sao bạn nói được còn con chó của bạn thì không), đến nghệ thuật chửi thề tinh tế đã mai một, Bryson khám phá ngữ pháp và nguồn gốc từ tiếng Anh khi kể câu chuyện hấp dẫn, thường rất buồn cười, về một thứ tiếng nông dân kém cỏi, hạng hai đã phát triển thành một trong những “ngành” tăng trưởng lớn nhất thế giới. Điều gì khiến tiếng Anh vừa gây phát điên vừa hấp dẫn không dứt? Lịch sử ngôn ngữ dí dỏm: theo chân tiếng Anh trên hành trình náo nhiệt từ một thứ tiếng nông dân hạng hai thành hiện tượng toàn cầu, với giọng hài hước nổi tiếng của Bill Bryson dẫn đường. Phát âm và chính tả: khám phá logic khó hiểu (và cả sự thiếu logic) đằng sau chính tả và cách phát âm tiếng Anh, từ những chữ câm đến vô số cách đọc “ough”. Tiếng Anh Mỹ và Anh Anh: khám phá những khác biệt thú vị và thường gây bối rối giữa hai phương ngữ lớn của thế giới nói tiếng Anh. Ngôn ngữ học bất ngờ: tìm lời đáp cho những câu hỏi bạn chưa từng nghĩ tới, như nguồn gốc của chửi thề và lý do thật sự khiến bạn nói được còn con chó của bạn thì không.$mota$, description_auto_translated = true
where id = 307 and language = 'en' and description_en is null and md5(description) = 'ba600c7f608da1377672c8d2b254597d';

-- 308 made-in-america
update public.books set description_en = description, description = $mota$“Hài hước, sâu sắc, uyên bác và cuốn hút khó dứt” (GQ). Bill Bryson tạm rời những xa lộ và đường làng của miền Trung nước Mỹ, vốn được ông khắc họa hài hước trong các cuốn sách bán chạy The Lost Continent, The Life and Times of the Thunderbolt Kid và Notes from a Big Country, để có một chuyến đi nhanh, hào hứng dọc “Route 66” của ngôn ngữ và văn hóa đại chúng Mỹ. Trong Made in America, Bryson kể câu chuyện tiếng Mỹ đã nảy sinh từ tiếng Anh ra sao, và trên đường đi, ông giải thiêng quê hương mình: giải thích vì sao một ngôi làng sa mạc bụi bặm chẳng có rừng (woods) cũng chẳng có cây nhựa ruồi (holly) lại thành Hollywood, vì sao Miền Tây hoang dã không hề được “chinh phục”, vì sao người Mỹ nói “lootenant” và “Toosday”, vì sao họ đã ăn đồ ăn vặt kém dinh dưỡng (junk food) từ lâu trước khi chính từ ấy được “nấu” ra, đồng thời phơi bày nguồn gốc thật của các từ G-string, blockbuster, poker và snafu. “Một tác phẩm vô cùng lém lỉnh, đầy sinh khí, phong cách và mọi phẩm chất tuyệt vời khác của nước Mỹ” (Will Self, Independent on Sunday).$mota$, description_auto_translated = true
where id = 308 and language = 'en' and description_en is null and md5(description) = 'e0c72aed370179007680ac21eade3fa4';


